import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

function Home() {
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);

  // Check login + load data
  useEffect(() => {
    const user = localStorage.getItem("user");
    if (!user) {
      navigate("/");
    } else {
      fetchProducts();
      fetchCart();
    }
  }, []);

  // Fetch products
  const fetchProducts = async () => {
    const res = await fetch("http://localhost:5000/api/products");
    const data = await res.json();
    setProducts(data);
  };

  // Fetch cart from DB
  const fetchCart = async () => {
    const user = localStorage.getItem("user");
    const res = await fetch(`http://localhost:5000/api/cart/${user}`);
    const data = await res.json();

    if (data && data.items) {
      setCart(data.items);
    }
  };

  // Save cart to DB
  const saveCartToDB = async (updatedCart) => {
    const user = localStorage.getItem("user");

    await fetch("http://localhost:5000/api/cart", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        user,
        items: updatedCart,
      }),
    });
  };

  // Add to cart
  const addToCart = (product) => {
    let updatedCart;

    const exist = cart.find((item) => item.productId === product._id);

    if (exist) {
      updatedCart = cart.map((item) =>
        item.productId === product._id
          ? { ...item, qty: item.qty + 1 }
          : item
      );
    } else {
      updatedCart = [
        ...cart,
        {
          productId: product._id,
          name: product.name,
          price: product.price,
          qty: 1,
        },
      ];
    }

    setCart(updatedCart);
    saveCartToDB(updatedCart);
  };

  // Increase qty
  const increaseQty = (id) => {
    const updatedCart = cart.map((item) =>
      item.productId === id ? { ...item, qty: item.qty + 1 } : item
    );

    setCart(updatedCart);
    saveCartToDB(updatedCart);
  };

  // Decrease qty
  const decreaseQty = (id) => {
    const updatedCart = cart
      .map((item) =>
        item.productId === id ? { ...item, qty: item.qty - 1 } : item
      )
      .filter((item) => item.qty > 0);

    setCart(updatedCart);
    saveCartToDB(updatedCart);
  };

  // Remove item
  const removeItem = (id) => {
    const updatedCart = cart.filter((item) => item.productId !== id);

    setCart(updatedCart);
    saveCartToDB(updatedCart);
  };

  // Total price
  const totalPrice = cart.reduce(
    (total, item) => total + item.price * item.qty,
    0
  );

  return (
    <div style={{ padding: "20px" }}>
      <h1>Welcome to Home Page 🎉</h1>

      <button
        onClick={() => {
          localStorage.removeItem("user");
          navigate("/");
        }}
      >
        Logout
      </button>

      <h2>Products</h2>

      {products.map((p) => (
        <div key={p._id}>
          <h3>{p.name}</h3>
          <p>₹{p.price}</p>
          <button onClick={() => addToCart(p)}>Add to Cart</button>
        </div>
      ))}

      <h2>Cart</h2>

      {cart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        cart.map((item) => (
          <div key={item.productId}>
            <h4>{item.name}</h4>
            <p>₹{item.price}</p>
            <p>Qty: {item.qty}</p>

            <button onClick={() => increaseQty(item.productId)}>+</button>
            <button onClick={() => decreaseQty(item.productId)}>-</button>
            <button onClick={() => removeItem(item.productId)}>
              Remove
            </button>
          </div>
        ))
      )}

      <h2>Total: ₹{totalPrice}</h2>
    </div>
  );
}

export default Home;
